def step_impl(context):
    context.data_package = create_data_package()

@when('I choose to delete the data package')
def step_impl(context):
    context.response = context.publisher.delete_data_package(context.data_package)

@when('I confirm the deletion')
def step_impl(context):
    context.confirmation = confirm_deletion(context.response)

@then('the data package should be permanently deleted')
def step_impl(context):
    assert context.data_package not in get_all_data_packages()

@then('the storage space should be freed up')
def step_impl(context):
    assert check_storage_space_freed(context.data_package)

@when('I cancel the deletion')
def step_impl(context):
    context.cancellation = cancel_deletion(context.response)

@then('the data package should not be deleted')
def step_impl(context):
    assert context.data_package in get_all_data_packages()

@then('the storage space should not be affected')
def step_impl(context):
    assert not check_storage_space_freed(context.data_package)

@when('I attempt to delete a non-existent data package')
def step_impl(context):
    context.response = context.publisher.delete_data_package('non_existent_package')

@then('I should receive an error message')
def step_impl(context):
    assert 'error' in context.response

@then('the storage space should not be affected')
def step_impl(context):
    assert not check_storage_space_freed('non_existent_package')
