    context.transactions[0]['category'] = category

@when('I categorize the first transaction as "{category1}" and the second transaction as "{category2}"')
def step_when_categorize_multiple_transactions(context, category1, category2):
    context.transactions[0]['category'] = category1
    context.transactions[1]['category'] = category2

@when('I change the category to "{category}"')
def step_when_change_category(context, category):
    context.transactions[0]['category'] = category

@then('the transaction should be categorized as "{category}"')
def step_then_transaction_categorized(context, category):
    assert context.transactions[0]['category'] == category

@then('the first transaction should be categorized as "{category1}"')
def step_then_first_transaction_categorized(context, category1):
    assert context.transactions[0]['category'] == category1

@then('the second transaction should be categorized as "{category2}"')
def step_then_second_transaction_categorized(context, category2):
    assert context.transactions[1]['category'] == category2

@given('I have transactions categorized as "Groceries" and "Dining"')
def step_given_categorized_transactions(context):
    context.transactions = [
        {'amount': 50, 'merchant': 'Grocery Store', 'category': 'Groceries'},
        {'amount': 30, 'merchant': 'Restaurant', 'category': 'Dining'}
    ]

@when('I view my transactions')
def step_when_view_transactions(context):
    pass  # This step is a placeholder for viewing transactions

@then('I should see transactions categorized as "Groceries" and "Dining"')
