### (2) Step Definitions in Python

```python
from behave import given, when, then

photos_sent = {}

@given('the photo "{photo_id}" is not marked as sent')
def step_given_photo_not_marked_as_sent(context, photo_id):
    photos_sent[photo_id] = []

@given('the photo "{photo_id}" is marked as sent to "{researcher_id}"')
def step_given_photo_marked_as_sent(context, photo_id, researcher_id):
    photos_sent[photo_id] = [researcher_id]

@when('the archivist sends the photo "{photo_id}" to the researcher "{researcher_id}"')
def step_when_archivist_sends_photo(context, photo_id, researcher_id):
    if researcher_id not in photos_sent[photo_id]:
        photos_sent[photo_id].append(researcher_id)
        context.notification = None
    else:
        context.notification = f'The photo "{photo_id}" has already been sent to "{researcher_id}"'

@when('the archivist checks if the photo "{photo_id}" has been sent to "{researcher_id}"')
def step_when_archivist_checks_photo(context, photo_id, researcher_id):
    context.photo_sent = researcher_id in photos_sent[photo_id]

@then('the photo "{photo_id}" should be marked as sent to "{researcher_id}"')
def step_then_photo_marked_as_sent(context, photo_id, researcher_id):
    assert researcher_id in photos_sent[photo_id], f'Photo {photo_id} not marked as sent to {researcher_id}'

@then('the system should confirm that the photo "{photo_id}" has been sent to "{researcher_id}"')
def step_then_system_confirms_photo_sent(context, photo_id, researcher_id):
    assert context.photo_sent, f'System did not confirm that photo {photo_id} has been sent to {researcher_id}'

@then('the system should notify the archivist that the photo "{photo_id}" has already been sent to "{researcher_id}"')
def step_then_system_notifies_archivist(context, photo_id, researcher_id):
    assert context.notification == f'The photo "{photo_id}" has already been sent to "{researcher_id}"', \
        f'Expected notification not received'
```

